<template><el-card shadow="never" class="filter-card"><el-form inline class="filter-form"><el-form-item label="类型"><el-select v-model="filters.task_type" clearable placeholder="全部类型" style="width:130px"><el-option v-for="item in typeOptions" :key="item.value" :label="item.label" :value="item.value"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="filters.status" clearable placeholder="全部状态" style="width:130px"><el-option v-for="item in statusOptions" :key="item.value" :label="item.label" :value="item.value"/></el-select></el-form-item><el-form-item label="缺陷类别"><el-input v-model="filters.defect_class" clearable placeholder="英文类别名" style="width:140px"/></el-form-item><el-form-item label="风险"><el-select v-model="filters.risk_level" clearable placeholder="全部风险" style="width:120px"><el-option label="低风险" value="low"/><el-option label="中风险" value="medium"/><el-option label="高风险" value="high"/></el-select></el-form-item><el-form-item v-if="showUserFilter" label="用户 ID"><el-input-number v-model="filters.user_id" :min="1" controls-position="right" style="width:120px"/></el-form-item><el-form-item label="场景"><el-select v-model="filters.scene_id" clearable placeholder="全部场景" style="width:160px"><el-option v-for="scene in scenes" :key="scene.id" :label="scene.display_name" :value="scene.id"/></el-select></el-form-item><el-form-item label="日期"><el-date-picker :model-value="dateRange" type="daterange" range-separator="至" start-placeholder="开始" end-placeholder="结束" value-format="YYYY-MM-DD" style="width:250px" @update:model-value="$emit('update:dateRange',$event)"/></el-form-item><el-form-item><el-button type="primary" @click="$emit('search')">搜索</el-button><el-button @click="$emit('reset')">重置</el-button></el-form-item></el-form></el-card></template>
<script setup>defineProps({filters:{type:Object,required:true},dateRange:{type:Array,default:()=>[]},scenes:{type:Array,default:()=>[]},typeOptions:{type:Array,default:()=>[]},statusOptions:{type:Array,default:()=>[]},showUserFilter:Boolean});defineEmits(['update:dateRange','search','reset'])</script>
<style lang="scss" scoped>.filter-card{margin-bottom:$spacing-md;border-radius:$border-radius-lg}.filter-form{display:flex;flex-wrap:wrap;gap:8px}.filter-form :deep(.el-form-item){margin-bottom:0}</style>
